// ─── File: src/main/java/com/bank/interest/service/InterestCalculatorService.java ───
package com.bank.interest.service;

import com.bank.interest.dto.InterestReport;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.function.*;

@Service
@Slf4j
public class InterestCalculatorService {

    @Value("${interest.rate:0.065}")
    private BigDecimal interestRate;

    record Account(String id, String type, BigDecimal balance) {}

    private final List<Account> accounts = List.of(
        new Account("SAV2001", "SAVINGS", new BigDecimal("125000")),
        new Account("SAV2002", "SAVINGS", new BigDecimal("45000")),
        new Account("CUR3001", "CURRENT", new BigDecimal("850000")),
        new Account("FD4001",  "FD",      new BigDecimal("500000")),
        new Account("FD4002",  "FD",      new BigDecimal("300000"))
    );

    public InterestReport calculate() {
        List<String> explanations = new ArrayList<>();

        // ═══ 1. UnaryOperator — apply interest (same type in/out) ═══
        UnaryOperator<BigDecimal> applyInterest = balance ->
            balance.add(balance.multiply(interestRate)).setScale(2, RoundingMode.HALF_UP);
        // Input: BigDecimal. Output: BigDecimal. Same type → UnaryOperator.

        List<BigDecimal> balances = new ArrayList<>(accounts.stream()
            .map(Account::balance).toList());

        List<String> before = balances.stream()
            .map(b -> "Rs." + b.toPlainString()).toList();

        // List.replaceAll(UnaryOperator) — transforms in-place:
        balances.replaceAll(applyInterest);

        List<String> after = balances.stream()
            .map(b -> "Rs." + b.toPlainString()).toList();

        explanations.add("UnaryOperator in replaceAll: balance → balance + (balance × "
            + interestRate + "). Same type: BigDecimal → BigDecimal");

        // ═══ 2. BinaryOperator — sum all balances (two same-type inputs → one output) ═══
        BinaryOperator<BigDecimal> sum = BigDecimal::add;
        BigDecimal totalPortfolio = balances.stream()
            .reduce(BigDecimal.ZERO, sum);
        // reduce(identity, BinaryOperator<BigDecimal>)
        explanations.add("BinaryOperator in reduce: BigDecimal::add → sums all balances: Rs."
            + totalPortfolio);

        // ═══ 3. BinaryOperator.minBy / maxBy ═══
        BinaryOperator<BigDecimal> minOp = BinaryOperator.minBy(Comparator.naturalOrder());
        BinaryOperator<BigDecimal> maxOp = BinaryOperator.maxBy(Comparator.naturalOrder());

        BigDecimal minBalance = balances.stream().reduce(minOp).orElse(BigDecimal.ZERO);
        BigDecimal maxBalance = balances.stream().reduce(maxOp).orElse(BigDecimal.ZERO);
        explanations.add("BinaryOperator.minBy/maxBy: min=Rs." + minBalance + " max=Rs." + maxBalance);

        // ═══ 4. BinaryOperator in Map.merge ═══
        Map<String, BigDecimal> perTypeTotals = new HashMap<>();
        for (Account account : accounts) {
            perTypeTotals.merge(account.type(), account.balance(), BigDecimal::add);
            // merge(key, value, BinaryOperator<BigDecimal>)
        }
        explanations.add("BinaryOperator in merge: aggregates per account type: " + perTypeTotals);

        // ═══ 5. UnaryOperator.identity() ═══
        UnaryOperator<String> identity = UnaryOperator.identity();
        String same = identity.apply("RELIANCE");  // returns "RELIANCE" unchanged
        explanations.add("UnaryOperator.identity(): returns input unchanged: " + same);

        return new InterestReport(before, after, totalPortfolio, minBalance, maxBalance,
            perTypeTotals, explanations);
    }
}
