// ─── File: src/test/java/com/bank/interest/service/OperatorTest.java ───
package com.bank.interest.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.*;
import static org.assertj.core.api.Assertions.*;

class OperatorTest {

    // ═══ UnaryOperator ═══
    @Test
    void unaryOperatorSameTypeInOut() {
        UnaryOperator<BigDecimal> doubleIt = amount -> amount.multiply(BigDecimal.TWO);
        assertThat(doubleIt.apply(new BigDecimal("100"))).isEqualByComparingTo("200");
    }

    @Test
    void unaryOperatorInReplaceAll() {
        List<BigDecimal> balances = new ArrayList<>(List.of(
            new BigDecimal("100"), new BigDecimal("200")));
        balances.replaceAll(b -> b.multiply(new BigDecimal("1.05")));
        assertThat(balances.get(0)).isEqualByComparingTo("105");
        assertThat(balances.get(1)).isEqualByComparingTo("210");
    }

    @Test
    void unaryOperatorIdentity() {
        UnaryOperator<String> identity = UnaryOperator.identity();
        assertThat(identity.apply("RELIANCE")).isEqualTo("RELIANCE");
    }

    @Test
    void unaryOperatorExtendsFunctionTT() {
        // UnaryOperator IS a Function — can be used wherever Function<T,T> is expected
        UnaryOperator<String> upper = String::toUpperCase;
        Function<String, String> asFunction = upper;  // widening — compiles!
        assertThat(asFunction.apply("reliance")).isEqualTo("RELIANCE");
    }

    // ═══ BinaryOperator ═══
    @Test
    void binaryOperatorSameTypeAllThree() {
        BinaryOperator<BigDecimal> sum = BigDecimal::add;
        assertThat(sum.apply(new BigDecimal("100"), new BigDecimal("200")))
            .isEqualByComparingTo("300");
    }

    @Test
    void binaryOperatorInReduce() {
        BigDecimal total = List.of("100", "200", "300").stream()
            .map(BigDecimal::new)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        assertThat(total).isEqualByComparingTo("600");
    }

    @Test
    void binaryOperatorMinByMaxBy() {
        BinaryOperator<Integer> min = BinaryOperator.minBy(Comparator.naturalOrder());
        BinaryOperator<Integer> max = BinaryOperator.maxBy(Comparator.naturalOrder());
        assertThat(min.apply(10, 20)).isEqualTo(10);
        assertThat(max.apply(10, 20)).isEqualTo(20);
    }

    @Test
    void binaryOperatorInMapMerge() {
        Map<String, BigDecimal> map = new HashMap<>();
        map.merge("A", new BigDecimal("100"), BigDecimal::add);
        map.merge("A", new BigDecimal("200"), BigDecimal::add);
        assertThat(map.get("A")).isEqualByComparingTo("300");
    }

    @Test
    void binaryOperatorExtendsBiFunctionTTT() {
        BinaryOperator<Integer> sum = Integer::sum;
        BiFunction<Integer, Integer, Integer> asBiFunction = sum;  // widening
        assertThat(asBiFunction.apply(10, 20)).isEqualTo(30);
    }
}
